(()=>{"use strict";const courses=document.querySelector(".site-header .site-courses");if(courses){document.addEventListener("click",event=>{if(courses.open&&!courses.contains(event.target))courses.open=false});courses.addEventListener("keydown",event=>{if(event.key==="Escape"&&courses.open){courses.open=false;courses.querySelector("summary").focus();event.preventDefault()}})}const menu=document.querySelector("#mobile-menu[data-site-menu-managed]");const opener=document.querySelector(".site-header .menu-button");if(!menu||!opener)return;const close=()=>{if(menu.open)menu.close()};opener.addEventListener("click",()=>{if(menu.open)return close();menu.showModal();opener.setAttribute("aria-expanded","true");document.body.classList.add("modal-open");menu.querySelector(".mobile-menu-close").focus()});menu.querySelector(".mobile-menu-close").addEventListener("click",close);menu.querySelectorAll("a").forEach(link=>link.addEventListener("click",close));menu.addEventListener("close",()=>{opener.setAttribute("aria-expanded","false");document.body.classList.remove("modal-open");if(!document.querySelector("dialog[open]")){opener.focus()}});const desktop=window.matchMedia("(min-width:1024px)");desktop.addEventListener("change",event=>{if(event.matches)close()})})();